// Imports a FastFlight run (MsData.FFT + MsData.FFC + a .mzcalib) into the old MetaboliteDetector 3.3
// raw-data cache (<stem>.bin + <stem>.idx) with the old binary's own importer. See make-cache.sh.
//
// Loaded with LD_PRELOAD into the old binary: it replaces main() and calls
// FastFlightImporter(dir), setCalibrationParameter(polynomial) and importData(stem, true, true),
// (drop the first point; keep scans of more than 50000 points uncompressed, skip the rest). Function addresses come from syms.inc, generated by make-cache.sh.
#include <dlfcn.h>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <string>
#include <vector>

namespace {

uintptr_t base;

template <class F> F fn(uintptr_t addr) { return reinterpret_cast<F>(base + addr); }

#define SYM(name, addr) constexpr uintptr_t name = addr;
#include "syms.inc"
#undef SYM

// MainWindow::readTOFCalibData: "Polynomial order: <n>", then "Parameter: <i> <value>" n+1 times.
std::vector<double> read_mzcalib(const char* path) {
    std::ifstream in(path);
    std::string token;
    int order = 0;
    in >> token >> token >> order;
    std::vector<double> poly;
    for (int i = 0; i <= order; ++i) {
        int index;
        double value;
        in >> token >> index >> value;
        poly.push_back(value);
    }
    return poly;
}

// argv: app ff_dir mzcalib stem
int import_main(int argc, char** argv, char**) {
    if (argc != 4) {
        std::fprintf(stderr, "usage: ff_dir mzcalib stem\n");
        return 2;
    }
    std::string dir = std::string(argv[1]) + "/";  // the importer appends the file names to it
    std::vector<double> poly = read_mzcalib(argv[2]);
    alignas(16) static char importer[1 << 16];
    fn<void (*)(void*, const char*)>(FF_IMPORTER_CTOR)(importer, dir.c_str());
    fn<void (*)(void*, const std::vector<double>&)>(FF_SET_CALIBRATION)(importer, poly);
    fn<void (*)(void*, const char*, bool, bool)>(FF_IMPORT_DATA)(importer, argv[3], true, true);
    fn<void (*)(void*)>(FF_IMPORTER_DTOR)(importer);
    std::printf("%s.bin\n", argv[3]);
    return 0;
}

}  // namespace

extern "C" int __libc_start_main(int (*main)(int, char**, char**), int argc, char** argv, void (*init)(),
                                 void (*fini)(), void (*rtld_fini)(), void* stack_end) {
    base = reinterpret_cast<uintptr_t>(main) - MAIN;
    using Start = int (*)(int (*)(int, char**, char**), int, char**, void (*)(), void (*)(), void (*)(), void*);
    auto real = reinterpret_cast<Start>(dlsym(RTLD_NEXT, "__libc_start_main"));
    return real(import_main, argc, argv, init, fini, rtld_fini, stack_end);
}
